  if (!Array.isArray(nums) || !Array.isArray(costs) || nums.length !== costs.length) return 'nums and costs need the same length.';
  if (nums.length < 1 || nums.length > 100000) return 'n is between 1 and 10^5.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each nums value is between 0 and 10^5.';
  if (costs.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each cost is between 0 and 10^5.';
  return null;
}

