function minCost(nums, costs) {
  const n = nums.length;
  const dp = new Array(n).fill(Infinity);
  dp[0] = 0;
  const waitingForHigher = [];
  const waitingForLower = [];
  for (let j = 0; j < n; j++) {
    while (waitingForHigher.length > 0 && nums[waitingForHigher[waitingForHigher.length - 1]] <= nums[j]) {
      const i = waitingForHigher.pop();
      dp[j] = Math.min(dp[j], dp[i] + costs[j]);
    }
    while (waitingForLower.length > 0 && nums[waitingForLower[waitingForLower.length - 1]] > nums[j]) {
      const i = waitingForLower.pop();
      dp[j] = Math.min(dp[j], dp[i] + costs[j]);
    }
    waitingForHigher.push(j);
    waitingForLower.push(j);
  }
  return dp[n - 1];
}

