  // Try every pair i < j, checking the jump rule directly on the values in between.
  const n = nums.length;
  const best = [0];
  for (let j = 1; j < n; j++) {
    best[j] = Infinity;
    for (let i = 0; i < j; i++) {
      const between = nums.slice(i + 1, j);
      const up = nums[i] <= nums[j] && between.every(v => v < nums[i]);
      const down = nums[i] > nums[j] && between.every(v => v >= nums[i]);
      if (up || down) best[j] = Math.min(best[j], best[i] + costs[j]);
    }
  }
  return best[n - 1];
}

