function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  // A narrow value range creates many equal neighbours, which is where the strict/non-strict rules matter.
  const span = size === 'large' ? (rand() < 0.5 ? 100000 : 50) : (rand() < 0.7 ? 4 : 100000);
  const costSpan = size === 'large' || rand() < 0.2 ? 100000 : 10;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (span + 1)));
  const costs = Array.from({ length: n }, () => Math.floor(rand() * (costSpan + 1)));
  return [nums, costs];
}
